import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Pumpkin plugin signing","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/signing/docs/index.md"},"headers":[],"relativePath":"tools/signing/docs/index.md","filePath":"tools/signing/docs/index.md","lastUpdated":1792508682000}`),a={name:`tools/signing/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pumpkin-plugin-signing" tabindex="-1">Pumpkin plugin signing <a class="header-anchor" href="#pumpkin-plugin-signing" aria-label="Permalink to “Pumpkin plugin signing”">​</a></h1><p><code>@pumpkin-plugins/signing</code> lets repository tooling sign and verify Pumpkin <code>.wasm</code> components with Ed25519. Call <code>signWasm</code> and <code>verifyWasm</code> directly when building your own tooling, or use the signing and verification GitHub Actions in a release workflow.</p><h2 id="signed-file-contents" tabindex="-1">Signed file contents <a class="header-anchor" href="#signed-file-contents" aria-label="Permalink to “Signed file contents”">​</a></h2><p>Signing adds <code>pumpkin.metadata</code> and <code>wasm_signature</code> custom sections to the WebAssembly file. The signature covers the module bytes and embedded metadata. <code>verifyWasm</code> checks that signature and returns the public key and release metadata. On its own, a valid result only means the file agrees with itself, so pass the trusted public key as the second argument: a file signed by any other key then comes back invalid with an <code>unexpected signer</code> error. Tools can inspect the sections or remove trailing signing sections, and signing replaces existing trailing signing sections before adding a new signature.</p><p><code>verifyWasm</code> reads the signature from a <code>wasm_signature</code> or <code>pumpkin.signature</code> section and accepts hex in either case, as Pumpkin does. It is stricter than Pumpkin in two places: it reads only the signing sections at the end of the file, and it needs a version 1 Ed25519 envelope rather than raw signature bytes. Files from <code>signWasm</code> pass both checks.</p><h2 id="metadata-ids" tabindex="-1">Metadata IDs <a class="header-anchor" href="#metadata-ids" aria-label="Permalink to “Metadata IDs”">​</a></h2><p>The metadata IDs <code>plugin_id</code>, <code>dev_id</code>, and <code>user_id</code> use the host&#39;s signed 64-bit range. Pass them to <code>signWasm</code> as <code>bigint</code>, or as <code>number</code> when they are safe integers; unsafe numbers and values outside that range are rejected. <code>verifyWasm</code> returns these IDs as <code>bigint</code> so JSON parsing preserves their exact values. Convert an ID to <code>number</code> only when it falls within JavaScript&#39;s safe integer range.</p><h2 id="keys-and-trust" tabindex="-1">Keys and trust <a class="header-anchor" href="#keys-and-trust" aria-label="Permalink to “Keys and trust”">​</a></h2><p>The secret key is a 32-byte Ed25519 seed, written as 64 hexadecimal characters. Keep it in a protected secret store, and distribute the public key through a trusted channel so consumers can pin the expected signer. A valid signature shows that the file matches its embedded metadata; it does not establish that the signer is trusted.</p><h2 id="github-actions" tabindex="-1">GitHub Actions <a class="header-anchor" href="#github-actions" aria-label="Permalink to “GitHub Actions”">​</a></h2><p>The actions support signing or verifying one file or a manifest of plugins in CI. They don&#39;t build plugins, so sign the exact <code>.wasm</code> artifact produced by your build job.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};